/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181211-9","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"文教委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３１年度入学希望申請の状況","agenda":"平成３１年度入学希望申請の状況","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"この数字をもとに戻してもいいという理由は何ですか。","respondent":"篠田学務課長","answer":"例年の数字が大体３割程度ですので、一応教育委員会としては、３割ぐらいの方が外に出るということで、７割ぐらいの方が利用されるだろうということで、考えているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"小学校も中学校も、抽選校が増えているということですけれども、増えている理由をどういうふうに、教育委員会は分析しているのでしょうか。それが１点。東海中学校を先ほど例に挙げて説明されたのですけれども、受入数に対して、圧倒的に入学予定者が多いですよね、７１人と。そのあたりを教えてください。","respondent":"篠田学務課長","answer":"それから東海中学校周辺の話ですが、確かに中学校全般に、受入枠に対して入学予定者数が上回っているところがあるのですが、これは例年同じような形でございまして、先ほど申したように約３割のお子さんは私立へ流れますので。","voiceIndex":9,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"例年３割は私立に行っているという問題ですが、たしか私の記憶では、違っていたら訂正しますが、小中一貫校をつくるときの理由に、私立へ流れないよう公立離れを防ぐ、たしかそういうことがあったと思うのですけれど、それについて、３割という数字はどういうふうになっているのか。当初の一貫校をつくるときの教育委員会の考え方に対して、現状はどういうふうにしていっているのか、その辺について伺います。","respondent":"篠田学務課長","answer":"過去の推移を見てまいりますと、中学校進学での流出といいますか、そちらを志望される方はここ数年、大体３割程度という形になってあります。昨年度は若干高かったのですけれども、総合すると大体３割程度です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"私立に行くというのはそれとして、先ほどおっしゃったようにそれぞれの家庭の教育方針、選択の問題ですので、別に悪いというつもりは全然ないのですけれども、しかし公立離れをとめていきたいという説得のされ方もあって、一貫校というものが進んできた。しかし私立に３割が流れているという数字に、変化はないというふうに見ていいのですか。その辺について伺います。","respondent":"篠田学務課長","answer":"これは品川区で取り組んできた結果の数字ですので、逆に言いますと何もしなければもっと、私立に流れる数は増えていた可能性も十分考えられる中で、こういった結果が出ているというふうに見ているところです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"もう一つは、もしかしたらこの間、毎年この報告の中にあったかもしれませんし、今回の学事制度審議会の中でももちろん内部ではきちっと分析されていると思うのですが、この増減の出入りがあって、１つの中学校、小学校等を基盤として、どこに希望して転出しているのが多いのか、逆にどこから来ているのが多いのか、そのフローといいますか、それがわかるようなものが資料としてあって、それをもとに。","respondent":"篠田学務課長、熊谷指導課長","answer":"これはやはりそのことが持つ影響力というのがかなりありますので、一応そういったものは、当然検討の中で土台では使っておりますけれども、一般には公開していない形で持っているものです。本区におきましては、９年間の一貫教育をしっかり定着させて、子どもたちの学力をつけてきたという自負がありますので、こちらについては引き続き、自信を持ってやってまいりたいと思います。","voiceIndex":16,"id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"だからそういう意味で、評価という部分でしっかりやっていただければと思います。先ほどトレンドなのか、そういうものは実際あって、いろいろな形で制度に生かしていただけるということで分かりました。それを表に公表してくださいという話ではないですけれど、しっかりとそうしたものを持ってやっていただいているのかなという、確認でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問","question":"一方で公立は、生徒を確保するために私学のようにさまざまな手を打つというか、いわゆる広告を打つとか、そういうことはしないわけではないですか。だけど公立学校というのが存在していて。教育委員会として、公立の学校にみんな来てほしいのか、いわゆるスタンスの問題で、そこはどのように考えているのか。","respondent":"篠田学務課長、熊谷指導課長","answer":"基本的なスタンスとしましては、当然区民の方は地元の学校に来ていただくというのが一番、本当に私どもはそのために取り組んでいるということが大前提です。そのための取り組みをかかすことはないということでやっているものです。ですので、もちろん公立学校としてぜひ、本区の教育には、先ほども申し上げたように力を入れて、そして自信を持ってやっておりますので、来てほしいという思いはありますが、ただやはりさまざまなお考えや子どもたちのそれぞれの特徴。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"これをなぜ聞いたかというと、いわゆる品川区の教育委員会としても、さまざまやっているわけではないですか。その辺はもう少し、もし本当に地元の学校に来てほしいというのであれば、私は一つのアピール方法として、品川区はこういうことをやっているよというのは、もっとアピールしてもいいのかなと思います。これだけ見ると、足りていないわけではないですか。","respondent":"篠田学務課長","answer":"ただ、いずれにしましても結果的に先ほどの延山小学校のように、当初２学級でその学区のお子さんを受け入れられる予定であったけれども、増えてしまった、超えてしまったという場合には、必ず教室数を確保し、必ず学区のお子さんが入れるように対応していくというものです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"もう毎年のことなのですけれど、今回小学校のほうですが、希望選択をとって抽選になった学校で、兄弟枠で何人申し込みがあって全員待機とか、５人兄弟枠で申し込みがあって２人だけ入れたが、３人は待機になってしまったとか、そういうところがあれば数字と合わせて教えてほしいです。受入枠６０のところは、７０入れるわけじゃないですか。もう受入枠を出さないほうがいいのではないですか。","respondent":"篠田学務課長","answer":"ただ、確かに委員ご指摘の形で受けとめられる方にとっては、納得がいかない部分があるのではないかですので、出さないこと自体がどうかというのも検討してみないと何とも言えないのですが、やはり一定程度。","voiceIndex":26,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"小学校１３校のうち、１０校が全員待機ということで、逆に３校はどういう状況なのか、教えてほしいです。受入枠は、たしか１０年ぐらい前は出していなくて、抽選になりそうな学校だけ、何人と入れたのです。どこの学校も枠があるのだから、全部出すべきだと言った記憶が、鮮明に残っているので、１０年前は出していないです、多分。兄弟枠の数のところだけ、教えてください。","respondent":"篠田学務課長","answer":"それから京陽小学校ですけれども、８名の方が希望されまして、７名の方が受け入れられて、１名が待機になっている状況です。日野学園は２６名の兄弟枠のご希望がございまして、１９名が受け入れられて、７名が待機されているという状況です。","voiceIndex":28,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今回の表を見ると、抽選校が小学校は２校、中学校は、３校増えているといった状況の中で、今、兄弟枠の話があったのですが、そちらでなくて、抽選にかかわる人数は全体で、小学校と中学校、何人この抽選に臨むのかという人数と、抽選に漏れて待機になる数、これは予想かと思うのですが、何人ぐらいになるのか、教えてください。","respondent":"篠田学務課長","answer":"抽選の人数ですが、合計数が出ていないので、後ほどお答えいたします。それから待機の人数が、小学校は全部で３２６名、中学校も同じく３２６名が待機になってあります。","voiceIndex":31,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこの作業を、もうちょっと区民にわかるように知らせてほしいと思うのです。そういった意味で、選択制がなかったときと、始まってからの現在と、事務量がどのぐらい違っているのでしょうか。その負担が増えている分、本当に効果があるのかどうか。人もお金もかけてやっていることで、それが本当に子どもたちや保護者の方々にとって、よい方向に行っているのかどうか。その辺はいかがでしょうか。","respondent":"篠田学務課長","answer":"事務量自体、単独では増えているものもありますけれども、当然集約されているものもあるということで、極端に事務量が増えているといったことはないと、認識しています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"受験勉強をして受験する、落ちてしまう場合は本当にがっかりするでしょうけれど、公立の学校で、自分の実力とは関係なくして選ばれないということ、この１０月に受付をして、１１月末に抽選ということで、待機者が３２６名ですか、小中学校それぞれともにいるという、待たされて決まらないということが、この時期の成長している子どもたちに与えるダメージとか、その手前で選ぶ努力というか。","respondent":"篠田学務課長","answer":"それから学校選択制の評価ですけれども、学校選択制自体は、品川の学校を変えていくという大きな目標がある中で取り組んできたものですので、開かれた学校にこれがつながってきたという過去の経緯もありますし、きちんとした形で。","voiceIndex":35,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、学校選択制の評価のところで、開かれた学校になってきていると、それは一部自分の地域以外のところにも目が向いているという意味ではあるかもしれません。全体に網をかけてしまって満足度が９０何％ありますと、そういったつかみ方ではなく、希望してこの選択制を使った方が、実際にどうなったのかというところまで、しっかりと検証していただきたいと思いますが、いかがでしょうか。","respondent":"篠田学務課長","answer":"それからマイナス面のお話で、地域での絡みというお話もございましたけれども、その辺のことに関しましては、今回、学事制度審議会の中で、全体の制度の見直し等もあって、例えば小学校の選択でこれまでブロック内で選べていた学校を、近隣校に限定するといった形で。","voiceIndex":37,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"校舎等いろいろな設備関係がどうか。個人的にいろいろ聞くと、教員がどうか。建物は、古い学校は本当に、よくしていただきたいと思いますし、一生懸命教員の方たちの声を聞いて育てていただければ、いい教員がたくさん増えると思うのです。私は、学校選択制はプラス面よりもマイナスのほうがずっと多いので、本当にやめていただきたい、これは意見を言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねします。やられていないとすると、選択の仕組みが変わったときの方式はどういうふうになるか、検討する予定があるのでしょうか。現状の認識でしょうか、兄弟枠がこれだけ待機になってしまうというところの認識と、今後の対応をお尋ねします。何対何とか、そういうことを高校のほうはやっているのですけれど、中学校はそれは特にないのでしょうか。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"それから区立の小学生が連携校の中学校に実際に出向いていって、中学校の授業を体験するなどしながら、ぜひ上がってもらいたい連携の中学校を実際に生で子ども自身が体験してもらうことで、地域の中学校を選んでもらおうという努力は。やはり兄弟が別々の学校になってしまいますと、ご家庭での負担等もありますので、できるだけ入れていきたいというのはあるのですけれども、一方で、学校選択の際に、これまでも周知はしてきているのですけれども、入れたとしても。","voiceIndex":40,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれありがとうあります。もう一つは、中学校の指導の話が先ほどあったのですが、小中一貫というのとまた別で、生徒指導とかそういう面で、中学校の教員の方が区立中学、しっかりやられていると思うのですけれど、そのあたりのお話をお願いします。","respondent":"大関教育総合支援センター長","answer":"生活指導面に関しましても、中学校と小学校、義務教育学校もあわせて、生活指導主任が毎月実施して、実際に生の様子を見ていただいたり、情報共有をして、小学校の教員を通じて、今、どこどこの中学校はこういう状況だという部分は。","voiceIndex":43,"id":"exchange-017"}]},{"id":"topic-02","title":"平成３０年 特別区人事委員会勧告に対する対応","agenda":"平成３０年 特別区人事委員会勧告に対する対応","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"非常に単純なことなのですが、公民較差という、この示されている金額が４桁で、今までこの間は３桁、１００円台、２００円台と低い金額だったのですが、今回９,６７１円と、こんなに数字が違っているというのは、なぜこんなふうに違いが出たかというところを教えていただきたいと思います。","respondent":"熊谷指導課長","answer":"月例給の公民較差の要因ですけれども、人事委員会によれば、平成３０年４月に実施しました行政系人事・給与制度の改正に伴い、職員構成に変化があったことによる影響というふうに聞いております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"職員構成の変化というか、具体的にわからないのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そうなのだけれど、ここだって具体的に示されているから、当然ご存じのことと思いますので、教えてください。わかる範囲で結構です。","respondent":"熊谷指導課長","answer":"こちらにつきましては、本日総務委員会でご説明するところですけれども、実際に今申し上げたとおり、こちらの行政系人事・給与制度の改正で、職員構成に変化があったことから、給料表がそれについて偏りが見られたというところしか、私のほうではご説明できないところです。","voiceIndex":53,"id":"exchange-020"}]},{"id":"topic-03","title":"大崎図書館分館の開館","agenda":"大崎図書館分館の開館","exchanges":[{"speaker":"南委員","kind":"質問","question":"蔵書数が示されているのですけれども、移転をしていった大崎図書館と合算してみたほうがいいのか、よくわからないのですけれど、この４万点という規模は、品川区内１０カ所ある図書館のどのぐらいか伺います。","respondent":"横山品川図書館長","answer":"分館の資料、４万点の予定ですが、区内の図書館でいいますと、源氏前図書館が３万８,０００点、大井図書館が４万６,０００点、二葉図書館２万８,０００点ですので、小規模な地区館と同等の蔵書数の予定です。","voiceIndex":61,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"裏面にレイアウト図が示されていて、ちょっと小さくてあまりよくわからないので、１点だけ伺いたいです。２つのパートに分かれて設定されているということはわかったのですけれども、入り口から入って、この辺が不鮮明なのですが、入り口が大体どこまであって、右側のほうは児童の図書ですか。多目的室のほうに行く、行き方がちょっとこれではわからないので、よろしくお願いします。","respondent":"横山品川図書館長","answer":"入り口から左側一帯が一般の書架になりまして、ここに一般図書も、児童図書も、絵本のスペース等もあります。真ん中に事務室が配置されていまして、その右側にトイレスペースと廊下がありまして、突き当たりが多目的室で、こちらで行事等を行う予定になっております。","voiceIndex":63,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この図の中で、前は読み聞かせのとてもすてきなお部屋があったのですけれども、その読み聞かせはどういうところで行われるのか、教えていただきたい。多分、細長くあるのは書架ですよね。座って読む場所というか、席はどのぐらい確保されているのか、その辺も教えてください。","respondent":"横山品川図書館長","answer":"読み聞かせのスペースですが、こちらの多目的室のほうで行う予定になっております。書架ですが、委員ご指摘のとおり細長い部分が書架になります。","voiceIndex":66,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もそうなのですが、疲れてしまって座って読める場所があったり、本の選定ができるとありがたいなと思うので、ぜひ、なるべく多くの席を確保していただきたいと思います。ここは地下ですよね、半地下ですか。そういった面で動線がどうなのかなと思いながら見ていたのですが、もちろん２方向避難になっているかと思うのですが、その辺の災害時の対策というか、避難ルートはどうなっているのか。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおり、こちらは芳水小学校の地下部分になります。出入り口としては、ロビーの１カ所があるのですが、そういう意味では１階の平面に面しておりますので、災害の際には最悪、窓からも出られるような形で対応しようと思います。","voiceIndex":68,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多目的室のところで行事をされるということで、乳幼児の読み聞かせもここでやってくださるということなので、多分広いスペースかなと思います。ぜひ充実した読み聞かせをしていただきたいと思いますが、読み聞かせも含めて行事はどのぐらいの間隔でやられるのか、教えてください。特に読み聞かせのところを。","respondent":"横山品川図書館長","answer":"そのほかに、季節ごとに例えばぬいぐるみおはなし会であるとかさまざまな行事をこれから実施していく予定ですし、今年度実施しております高齢者支援事業についても、こちらで拡大していこうと考えています。","voiceIndex":70,"id":"exchange-025"},{"speaker":"つる委員","kind":"確認","question":"地図上でしか私もわからないのですが、表の図でいうと、若干ですが、体育館とかぶるところがあるのですよね。多目的室のほうは、位置的にはステージ直下になるのですか、あとは事務室とかその辺も、音の影響とかいうのは躯体の関係で、専門的なところでしっかりされていると思うのですが、この辺の配慮など、そういう意味では大丈夫か確認だけ、お願いします。","respondent":"横山品川図書館長","answer":"こちらは学校改築の途中で図書館の併設が決まりまして、その際にご心配いただく声をいただいておりますので、図書館の工事の際には特に音の伝導について配慮していただくように、業者の方にお願いしているとともに、音になるべく影響のない、多目的室やトイレ。","voiceIndex":72,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"細かい部分ですけれど、この図書館部分にＡＥＤは設置されるのでしょうか。もしされるのであれば、どのあたりに設置しますか。","respondent":"横山品川図書館長","answer":"ＡＥＤについては各図書館に設置していくところですので、分館についても設置していきたいと考えています。場所については、まだ引き渡し前ですので、そちらを確認してから設置場所を確定していきたいと考えています。","voiceIndex":74,"id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。先ほど飯沼委員とのやりとりの中で、収容人数は決められていないという話だったのですが、そこを改めて、何の収容人数が決められていないのか教えてください。","respondent":"横山品川図書館長","answer":"図書館の性質上、１日そちらに在館される方は少なくて、入れかわり立ちかわり、もしくは席を利用しないでご利用なさる方も多いという形で、出入りの人数はカウントしているのですけれども、定員はここまでなので入ってはいけませんということはできませんし。","voiceIndex":76,"id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問","question":"でも出入りが多い施設というのはたくさんあって、その施設のキャパシティに対して、どれだけの人が入れるかというのは、ある程度決まっているものですよね。要は利用のときにそれ以上とか、以下とかいう部分はないのかもしれないけれど、一定の収容人数というのは、設定しておかないといけないのではないのかと思うのですが、その辺もう一度教えてください。","respondent":"横山品川図書館長","answer":"法令上で、例えば消防法で１００人とか１,０００人とか、大まかな規定の制限はあると思うのですけれども、図書館を建てるとき、何人予定でというような決まり自体はない形になります。","voiceIndex":78,"id":"exchange-029"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、法律上の何かしらは、あるわけですよね。収容人数はあると思うのですが。大まかに、例えば２８８人ですとかいうのではなくて、３００人ですというものなのかあれですが、何らかの法令上のもので、収容人数というのはあるのではないか。施設はどこでもそうだと思うので、それを教えてください。","respondent":"横山品川図書館長","answer":"そのような意味ですと、席で各図書館をご案内しているような形で、非常に出入りの人数よりは少ない形ですが……。","voiceIndex":80,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"で、体育館の下というのも、半地下というのはどこのことかなという関係で、多目的室に結構な人がおいでになったとき、もしもの場合にはどうするのかなと、ちょっと気になったので、そのあたりの避難も含めて、２方向避難との関係も含めて教えてください。","respondent":"横山品川図書館長","answer":"多目的室の前も窓で、外に出られる状態、多目的室の前は駐車場になりますので、段差としてはそんなにない状態になっています。２方向避難については、出入り口としては１カ所しか設けていないのですが、消防法についてはクリアされている状態で、建築されていると聞いております。","voiceIndex":83,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"２方向避難との関係で、今わからなかったのですが、消防法でクリアされているということはわかったのですけれども、２方向避難が設定されていなくてもいいという、そういう理解でいいのですか。","respondent":"横山品川図書館長","answer":"申しわけございません。２方向避難について、これでいいというような確認のところまで把握しておりませんので、後日確認します。","voiceIndex":85,"id":"exchange-032"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"もう一つは、園によってだと、全園でないと思うのですけれど、４歳児も午睡時間をなくしている、４歳児の当初からではないと思うのですけれど、そういうふうにしているところがあると聞いているのですけれど、その点についての見解を伺いたいと、品川の保育内容ということに関して、伺いたいと思います。","respondent":"佐藤保育課長","answer":"２点目の４歳児も、ですが、こちらに関しては基本的に午睡をする取り扱いです。お子さんの体調や状況によって、午睡をしない場合もあるかもしれませんが、それは個別に対応しています。基本は５歳児からというふうに考えております。","voiceIndex":97,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"１日過ごせる体力がついているというふうな説明でしたけれども、小学校に上がれば当然午睡の時間はないし、当面は午前中授業だけれども、２学期あたりから５時間以上も入ってくるというふうに思っているので、そういう点で体力をつけていくということは大事だなと思うのですが、その１日過ごせる体力という点で、個々の子どもの状況によっても、発達とか生まれた月とか、一律にしていくというのもなかなか。","respondent":"佐藤保育課長","answer":"４歳児に関しましては、ある時期から午睡を取りやめるとか、どういう感じでやっていくかというのは、今後の研究課題かと考えております。","voiceIndex":99,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"とりわけ保育園は１日保育ですし、子どもによっては朝早くから夕方遅い時間まで、保育園での保育されている状況もあるわけですから、そういう点ではやはり、成長、発達の段階にある子どもの保育というのは本当にきちんとした、過去のいろいろな経験、蓄積の上に捉えていくべきではないかと思いますので、きちんとした考え方のもとでの指導が必要なのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"写真入りで、すごく網羅した、初めてですよね、こういった研修の中身がきちんと書かれたものは。よくつくっていただいたと思います。この資料は、どういう方が携わってつくってくださったのかというのが一つ。研修というのは本当に、保育の質を向上させていく上で日々大事なことですけれども、研修の中身を作成するのは、どういった方が携わっているのか、その２点を教えてください。","respondent":"佐藤保育課長","answer":"２点目のご質問にもつながりますけれど、研修の中身というところもその現役の園長、ＯＢの園長も５人ほどいらっしゃいますけれど、そういった中で、これまでの蓄積に応じた効果的な保育の研修について、さまざまな研修を実施しているところです。","voiceIndex":102,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この研修の中身というのは、公立の保育園と私立の両方とも、多分主に認可保育園であろうなと思うのですけれども、今みたいに保育施設がいろいろできてきている中で、品川区のお子さんに対する責任といった意味で、すごく頑張っていると思っているのです、私立園が増えて、大変だなとは思っているのですけれど、その辺の研修のパイというか、品川区がどの程度まで。","respondent":"佐藤保育課長","answer":"区としての研修の実施といいますと、私立保育園等への働きかけだと思うのですけれども、私立は私立で、先ほどご説明したように各事業所や園の方針で保育を行っておりますし、その考え方は当然尊重されるべきですが、区といたしましては共通的なもの。","voiceIndex":104,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保護者の方がされていて好評の１日保育士体験を、保育課の方がされるというのはとてもいいことだと思います。保育の入園申請にいらっしゃる父母の皆さんとか、子どものことをまず理解する、その子どもたちを思い描くことで、大変なときも頑張れると思うので、ぜひ皆さんに体験をしていただきたいと思います。","respondent":"佐藤保育課長","answer":"現場の保育士のほうも、保育課も頑張って保育士の確保をしておりますけれども、今後はどちらかというと出前形式みたいな、現場に訪ねていって、より保育を学んでもらうような形にしたほうがいいだろうという声が内部でも出ていますので、今年度は研修の再構築をしておりますから。","voiceIndex":106,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出前もいいかなと思うのですけれども、人手不足は深刻です。本当に深刻です。そんな状況でお仕事をしているという、病児保育も全部は役に立たないのです。これはお願いしておきますが、課長だけの問題ではないので、部長にもしっかり聞いていただいたと思いますので、ぜひ検討の材料にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-039"},{"speaker":"鈴木（博）副委員長","kind":"提案","question":"保育園で生命を脅かすような事態、非常に大変な事態というのは事故で、食物アレルギーのアナフィラキシーショックもそうですが、例えば鉄棒から落ちたとか、転んだとか、宙返りしたときに肱が抜けた、けがをした、そういうときの初期対応を保育士がある程度できるようにするトレーニングというのは必要ですから、ぜひ事故対応を項目の中に入れていただきたいと思ったのですが、その点はいかがでしょうか。","respondent":"佐藤保育課長","answer":"委員ご指摘の事故の関係の対応についても、十分保育士のほうで学ぶ機会を設ける予定です。","voiceIndex":109,"id":"exchange-040"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"親との関係もすごく大事なので、コミュニケーション能力というのは非常に大切です。特に今はいろいろな親の方がいらっしゃるので、そういう研修も十分やるように、これは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"受けていないとしたら、異動で今後、保育園に行ったとき、どうなるのかというところを伺いたいです。どのようにして参加されているのか、参加されていなかったら、次の職場のためにどういうふうになるのかということです。それから、先ほど鈴木博副委員長からのお話でもあった、コミュニケーションのほうですが、現在は保護者に対する対応についての研修は、されているのでしょうか。","respondent":"佐藤保育課長","answer":"２点目の保護者支援に関しましては、今年度は保護者との良好な関係構築のためのコミュニケーション能力と、保護者ニーズが多様化しているという理解を進める関係で、講義等の研修を実施しております。","voiceIndex":112,"id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童センターにはいらっしゃらないのでしたか。いらっしゃったら、保育園のお仕事と違うので、その後についてどうなのか教えてください。","respondent":"高山子ども育成課長","answer":"その後、また保育の現場に戻れば、先ほど保育課長が答弁されましたように、改めて保育現場における研修体系に基づいて再教育ということになるかと思います。","voiceIndex":114,"id":"exchange-043"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。保育の質の向上と、今、特に言われているのですけれど、今回この資料を見ていても、保育の質なのか、保育士のいわゆる質というのか、研修だったり処遇改善だったり、そこが保育の質になっているのか。私はほぼほぼ保育士の、いわゆる働き方がどうなのかがイコール保育の質に見えるのですけれど、区としてどういうふうに考えられているのか。","respondent":"佐藤保育課長","answer":"３つ目が委員ご指摘の人、保育士の質。この３点と考えておりまして、どれもバランスよく進めていきたいと考えているところですが、本日の所管事務調査に関しましては、どちらかといいますと保育士の質を高めるという観点で、まとめさせていただいているところです。","voiceIndex":116,"id":"exchange-044"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"突然の報告だったので、受けとめられないのですが、これは７月１９日に都と合同検査に入ったということですが、きっかけは一体何でこの合同検査に入ったのか、保育士が適正に配置されていないというのはどこの部分に適正に配置されていなかったのか、まず２点お伺いします。","respondent":"佐藤保育課長","answer":"それで都と相談をした結果、合同検査が必要ではないかということで、７月１９日に行われたものです。７月１９日に実際に指導検査に行ったところ、朝の保育士の体制が１名不足しているというのを確認しました。","voiceIndex":127,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"朝の配置というのは、早番の保育の体制が、多分何カ所かでやられているところに、正規の保育士がいなかったということですか。非正規の資格のない人がやっていたということなのか、それも何人必要なところに何人しか配置されていなかったなど、もう少し具体的に教えてください。","respondent":"大澤保育支援課長","answer":"早番は７時半からになりますけれども、本来は７時半から２名、保育士がいなければいけないところを、１名しか配置していなくて、具体的には８時から出勤する職員が次のシフトになりますので、７時半から８時の３０分間、１名で対応していたです。","voiceIndex":129,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"朝の保育のところは、本当に１名しかいなかったということは、ほかに非正規の人がいたのですか。本当に重大な問題ですよね。何かあったとき、１人の保育士ではとても対応できないというところなので。この３０分ですけれど、どのぐらいの期間においてこれがされていたのか、その理由はなぜなのか。これは大問題だと思うのですが、そこのところはどう判断をされているのでしょうか。","respondent":"大澤保育支援課長","answer":"保育士の急な退職等により、体制が整えられずに平成３０年４月から１人で対応していたということでございました。私どもも大変、これは重要な案件だと考えております。","voiceIndex":131,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"急な退職ということですけれども、職員が確保できなかったという受けとめなのでしょうか。相談体制とか、私立なので、園で対応することかと思うのですけれど。この辺の防止策というか、公立だと職員が不足したらすぐ連絡が来ると思うのですが、防止策をどう考えていらっしゃるのかということと、この４６０万円というのは単純にその間の職員に対しての給与関係なのかどうか、そこも教えてください。","respondent":"大澤保育支援課長","answer":"返還額ですが、こちらにつきましては、保育士が規定どおりに配置されていることを前提に、加配している保育士に対する加算部分を、４月から７月分を返していただくという考え方です。","voiceIndex":133,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"今、毎月保育士の数は把握していますということにおいて、報告に不正があったのですか。正しい報告がされていたのかどうか。その辺は、人が確保できなかったという問題だけではないと思うのですけれど、その辺どうだったのか。報告上はちゃんとされていたのか数字がごまかされていたのかどちらですか。","respondent":"大澤保育支援課長","answer":"基準の保育士の配置としては足りています。ただ、シフト上、早番の方を２名入れていなかったという考え方になります。","voiceIndex":135,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今ここでいろいろ言っても仕方がないので、ぜひそういうことがないように、これは倫理の問題でもあると思うので、チェックできる方策を考えていただきたいし、事故がなかったからよかったですけれども、このときに大きな災害があったりしたら、たかだか３０分といっても、とても大事な時間帯だと思うので、ぜひ指導の面でのご努力を、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"その辺について説明がなかったので、伺いたいと思います。だからここは、２人の配置をしないと、受け入れも含めてできないという状況であったと思うのですけれど、その点についてはどういうふうに説明があり、どうなっていたのか伺います。それと３点目に、返還金額が４６０万円というのと、１０日分の１４万円という説明があったと思うのですけれど、この関係がよくわからないので、もう一度お願いします。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"今回の指摘につきましてあざみ会は、もちろん反省しておりまして、８月からすぐに非常勤の方を雇ってシフトをきちんと整える対応をしております。４名受け付けた際は、本来ですと保育士は２名必要です。その４名を受け入れたにもかかわらず、保育士が１名しかいなかった、この状態が１０日あったです。","voiceIndex":138,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"その処分が適切だったのかどうかは、私は基準も何も認識もないのでわからないですけれど、適切だったのだろうという理解をしました。１名しか配置できなかったのが１０日間あったという点について、品川区としての見解と、こういう状況を出したことについて、区としての反省とこれからの指導を含めて、どういうふうに捉えているのか、伺っておきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"今回これに伴いまして、区の病後児に関する要綱、委託事業者との契約の仕様の変更、こういったことで、より正しいやり方でやれるよう、対応してまいります。","voiceIndex":141,"id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"病後児保育の受け入れについては、ここの保育園との変更というのは当然ですけれども、考え方として病気になってその後の何日間、１週間とか、そこをどういうふうに保育の手当をしようかというところなので、一定程度期間も予想できると思います。当然予約制になっているわけですけれども、そういう点で配置ができなかったのであれば、私は保育園側としては、気持ち的には、いい、悪い別にして……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"もちろんそのつもりで質問しています。受け入れたからには絶対、今日受け入れて、明日、保育を受け入れるということでは、病後児保育だから必ずしもそうではないと、私は思っています。その点について、見解があれば伺いたいし、なければ強力な意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-054"},{"speaker":"渡部委員","kind":"確認","question":"端的に、７月にそういうことがあって、８月から大丈夫ということで、そこはいいと思います。こういうことがあったときに、品川区内のほかの保育園はどうなのだろうと、当然聞き取りなり何なりなさっていただいたと思いますけれど、問題はないという確認だけさせてください。","respondent":"大澤保育支援課長","answer":"先ほど申し上げましたように、保育士の数、またシフト表は保育支援課でチェックしておりますが、今回のことを受けまして、９月１１日の私立保育園長会で、職員配置のルールにつきまして、改めて確認しています。","voiceIndex":146,"id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう１つは、どこからのお金をどこに返還するのでしょうか。４６０万円で４カ月なので、２５日で割ると１日４万円ぐらいでしょうか。加配している保育士の分の金額はどういうふうにして出ているものなのか、教えてください。","respondent":"大澤保育支援課長","answer":"８月から改善されていますので、４月から７月分の返還ということで、今回は考えております。４６０万円の金額ですけれども、運営費の一部になりますので、具体的には今後の運営費からの相殺という形をとろうというふうに考えております。","voiceIndex":148,"id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"運営費という大枠の中で、というお話ですね。その加配の分の４６０万円というのは、どういう計算で出たのか、教えてください。","respondent":"大澤保育支援課長","answer":"保育士が規定どおり配置されていることがまずあって、その上に加配をした場合の加算部分ですので、具体的には主任保育士加算、３歳児配置改善加算、特別支援保育加算の部分を返還していただくという計算になっております。","voiceIndex":150,"id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"細かいところまでありがとうございました。今、ほかの委員からもありましたけれども、非常に大変なことであったわけなので、今後このようなことが起きないようにお願いいたします。それも東京都からの話で発覚したということですので、区としても保育園行政についてはかかわりは非常に深いと思いますので、ぜひその辺をきちんと、先ほどの改善策をしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4960#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":42046,"voices":154}},{"id":"h30-20181211-5","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"総務委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１２ページの財務４表増減額内訳が一番整理されていると思うので、ここから伺いたいと思います。その対比で、人件費は、何に当たるものなのかご説明いただきたいと思います。","respondent":"品川財政課長","answer":"ほぼ、委員がおっしゃったとおりです。基本的に、委託関係につきましては、この表の中では物件費という形で出しています。反対に人件費は、俗に言う区職員の給与、それから退職金等になるという形になってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、今まで行政がやっていたものが委託という形になると物件費で算出される。そういうところでは、このつくり方は区が特別につくっているわけではないのですけれども、実際の姿がわかりにくく実態との乖離が生まれてしまうのではないかと思うのですけれども、その点についてはどのようにお考えでしょうか。","respondent":"品川財政課長","answer":"要するに、前年度の退職人数等、例えば平成２８年退職人数と平成２９年退職人数など大きく数字が変わってしまうというふうな場合もありますので、なかなかこの表だけでは一概にいろんなことが示せるものではないと思っています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、一般的に民間の会社ですと、６ページの普通会計の貸借対照表を見れば、大まかなことはわかると思うのです。それで、公表にあたっては、ホームページに品川区公会計レポートを上げると思うのですけど、公表時期としてパンフレットは、「同時期」と資料に書いてありますけれど、どの程度の内容を掲載するお考えかお聞きしたいと思います。","respondent":"品川財政課長","answer":"いろいろ民間の貸借対照表とは、やはりどうしても行政の貸借対照表は違うやり方になってしまいますので、民間の財務諸表の知識でそのまま見てしまうと、いろいろ疑問点は出ると思いますけれども、行政の財務諸表のあらわし方にのっとって現在やっております。","voiceIndex":12,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうなると左右が一致しなくなるのではないかと、私は思って、それはどうなっていくのでしょうかというあたりはお答えいただいたのですけど、理解できなくて、その辺をどういうふうな扱いにしていくのか、ぜひ伺いたいのと、それからパンフレットには減価償却費は累計額だけがたしか載っていて、そのことが出ていないので、おっしゃったように、普通の民間の会計の知識で見ると。","respondent":"品川財政課長","answer":"いろいろ減価償却の点につきましては、現在のこのやり方ですと、民間の財務諸表と見比べていただくと疑問点が出てくるかと思うのですが、今、新しい公会計システムでやっておりまして、平成３０年度の決算から財務諸表を新しくつくるのですけれども。","voiceIndex":15,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"パンフレットもそのとき検討するということでよろしいですか。","respondent":"品川財政課長","answer":"詳細については、今現在、検討しているところですので、少しお待ちいただければと思います。","voiceIndex":17,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから公会計レポート、毎年きちんと見ているわけではないのですけれども、これはこういう状況であるみたいな、確かにレポートだなと思うのですけれど、もう少し評価みたいなところまで踏み込んだ表現がされると、せっかくホームページ上で公開されていますので、区民の方で財政のことがすごくよくわかる方もたくさんいらっしゃると思うので、そういう公表の仕方も。","respondent":"品川財政課長","answer":"表記の方法については、今後どうしていくか、検討していくということになると思います。他自治体で先行して、いろいろと新しい方式を用いた財務諸表を作っているところもありますので、そういうところも参考にして考えていきたいと思ってあります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ検討していただきたいです。それから、ほかの自治体で既に始めているところには、成功している例もありますが、一回やってみたけど結局評価がうまくできなくて、議員の中での評価もうまくいかなくて、すぐに変更したという、ある意味、失敗しながら模索をしているところもありますので、ぜひそういうところも参考にしていただけるといいかと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"ということは、そのまま右側にいきまして貸借対照表の「資産」の「公共資産」の中に「道路、橋、公園、学校など」とありますが、これは、つくったときのコストがこのまま資産として残っているということなのでしょうか。教えてください。","respondent":"品川財政課長","answer":"「公共資産」のところです。公共資産については、今、普通建設費の費用というような形での積み方になっており、そういったところで固定資産という考え方とちょっとずれがあるというところが、今のやり方の問題点です。","voiceIndex":23,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"それと、ここには道路、橋、公園、学校とあるのですが、橋というのはやはり区で持っている橋もあるのですか。それで、公共施設の中で、おそらく土地も評価されていると思うのですが、公共資産の中の土地の評価は、ここに出す金額は、路線価をもとにして表記しているという解釈でよろしいのでしょうか。それとも別のやり方で算出した資産額をここに載せているのでしょうか。","respondent":"品川財政課長","answer":"ですので、基本的には路線価で、本来は固定資産という形も出したいというところがあるのですが、それは今度の財務諸表で多分なってくるのではないかと考えています。そこが、先ほど申しました検討次第ということになります。","voiceIndex":25,"id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"わかりました。資産において、投資などが７５６億３,０００万円とあります。この中には有価証券等も入っていますが、それに流動資産をたしあわせる総額１,０００億円を超えるというのは、すごい健全財政というのか、すごいと評価されるというのか。一応感想だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-010"}]},{"id":"topic-02","title":"特別区人事委員会勧告に対する特別区長会の対応","agenda":"特別区人事委員会勧告に対する特別区長会の対応","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"特別区人事委員会がどういう形でやるかわからないですが、もし来年やったときに、寄り戻しというか、一気にまた来るような気がするのですけど、そういう想定はせず、今回の引き下げに関しては従わないということなのか。来年、また調査をしたときに民間が低いという結果になったときは、ダブルパンチとなるのではないかと、すごく危惧するところなのですけれど、実際にどこまでお考えになっているのか。","respondent":"黒田人事課長","answer":"特別区全体の方向性としましては、特に主任の高位号給のところにかなり山があるということで、主任については係長職に任用するということで、労使との妥結の中でも係長選考を、特例選考というのを実施するということで、一定程度。","voiceIndex":33,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"前回の総務委員会での報告では、下げるというお話だったと思います。そして、毎年この基準でやりますということで、我々議会にも報告されているわけですが、では毎回、何かによって変わっていってしまうというのだったら、何も人事委員会の意見を聞く必要もないし、区は区の独自の考え方でやればいいという制度に見られてしまうのではないですか。その辺についてご見解をお聞かせください。","respondent":"黒田人事課長","answer":"今回は人事制度を改正し、８層制から６層制に変えた中で、職員構成が一過性というのでしょうか、どうしても階層を少なくしたことによって、一部ひずみが出たというところで、民間の比較の中でも、今、景気が緩やかに回復しているという中で。","voiceIndex":37,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"要は、毎年、人事委員会からこういうふうに勧告されるわけですから、やはりその辺に疑問を非常に感じますので、それだけはちょっと指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"２つ伺いたいのですけれども、改定しないということは、具体的には条例の改正という手続にはならないということでよいのか。もう一つは特別区長会の見解を伺いたいのですけれども、今回、民間との比較で、とりわけ職員構成について比較したことで、こういう人事委員会勧告が出たわけですけれども、職員構成を比較することに合理性があるのか。特別区長会はそこをどう考えているのか伺いたいと思います。","respondent":"黒田人事課長","answer":"２つのご質問をいただきましたけれども、１点目の条例改正につきましては、今回、改定しないことを決定したですので、給料表の改定、特別給の改正を実施いたしませんで、条例改正を今回、提案しないということになりますので。","voiceIndex":41,"id":"exchange-014"}]},{"id":"topic-03","title":"上場株式等に係る配当所得等に関する住民税の税額再算定","agenda":"上場株式等に係る配当所得等に関する住民税の税額再算定","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"これは、品川区だけで起きていることなのかどうかというのが非常に興味深いところで、品川区の税務課が解釈を誤り税額の再算定につながってしまったというのか、２３区全体を見て、こういうことが、あちらこちらの区で間違った解釈をし税額の再算定になっているのか。できれば、増額分の一番多い人に幾らぐらいの増額になって、減額の方でどれぐらいが減額になるのかというのがわかれば教えてください。","respondent":"伊東税務課長","answer":"この解釈に関しましては、今、２３区レベルで聞いているところでは、２１区ほどが品川区と同じような解釈をしていたと聞いているところです。","voiceIndex":49,"id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今後の周知の部分で、郵送、送付するということですので、通常郵便なのか、どうなのかは別にしても、しっかり手元に届いて、配付して、中身を確認していただけるような形で、８０名程度ということなので、しっかり手元に届くようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"再算定ということは、つまりは間違ってしまったということだと思うのです。は具体的な手続の中でもそういうことが必要ではないかと思うのですけれども、その点を伺いたいと思います。あわせて、２３区の中で、品川区を含め２１区が今回こういう対応をするということですけれども、これに気づいたきっかけは何なのか。いつ頃気づいたのか。その点についても伺いたいと思います。","respondent":"伊東税務課長","answer":"それと、今回の発覚の経緯ですけれども、平成１５年の税制改正の中でこのような形がとられたということはあるのですけれども、そのとき、自治体まで、正確に説明が伝わり切れていなかったというところはあるのかと思っているところです。","voiceIndex":53,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつ気がついたのかということで、今年の９月に、ある区からということであれば、品川区というよりも、２３区の中のどちらかの区がこの仕組みに気づいて、２３区の例えば課長会などで共有しながら対応を考えていたということになるのか、伺いたいと思います。私も大変不勉強であれなのですけれど、これは特別区だけの問題なのでしょうか。いわゆる全国的なことになるのでしょうか。","respondent":"伊東税務課長","answer":"課長会といいますか、その中で情報が漏れ伝わってきたということは確かにそのとおりでございまして、それでどうしていこうかという話があったところなのですけれども、そもそも平成２９年の改正の中で、そういうことが明確になったということも一方であったということで。","voiceIndex":55,"id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"こういったことがないよう、今後とも点検をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり私はこういうときは国に対して、通達が悪かったのではないかという、謝罪を逆に要求するようなことが必要ではないかと。これは、品川区だけというならわかりますけど、日本全国で、おそらく同じような状況だと私は思うので、本当に一度ぐらい、国に謝罪を求めますというような意見書を出していいのではないかと思いますけれど、いかがですか。","respondent":"伊東税務課長","answer":"平成１５年の改正で、平成１７年度からそうなったというところなわけなのですけれども、今回、こういうことが発覚しまして、都および国にも、そのときの状況、なぜ我々がそういう解釈になったのかというところについても説明を求めたところですが。","voiceIndex":59,"id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つだけ、かなうのであれば、私はやはり、区が悪かったというようなことは書かないで、区民に報告してほしいです。国の曖昧な通達によって、こういう事件を起こしてしまったということは、やはりそもそもどこが決めたんだという話ですから、私はちょっとそういうふうにしていただきたいという意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-021"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"そこの家は、たまたま、聾というのですか、生まれつき難聴の人ですから、やはり声の出し方が、ちょっと違うわけです。企業に向けて、品川区は何かやっているのですか。もちろん、品川区の職員に対しての研修というのは、庁内だからあれなのですけど、大体、品川区の企業も大きな企業がありますので、そういうところにはどういう周知というかをしているのか、教えてください。","respondent":"島袋人権啓発課長","answer":"ですので、おのおののケースに関しまして、特に人権啓発課に上がってくるということではございませんで、まずは生活圏ごとの連携・情報共有から、その部門におけるケース対応までをしっかりと連携してやっているというのが、このシステムの流れです。","voiceIndex":66,"id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問","question":"それで、東京都が言っている警察がすぐ動くというのも、動くケースと動かないケースがあるというのは間違いないわけですから、それは本当にどこからどこが暴力なのか、警察も、動かないときは何度言っても動かない。数値は出ているわけですから、この背景に何があるかを、東京都に聞いたらそう言っていますというのはちょっと違うのではないかと思うので、しっかりやってくださいということ。","respondent":"島袋人権啓発課長","answer":"今後、私どもも、やはりこのアンケートをとったことによりまして、また次に何をしようかと、企業といろいろ検討しながら進めていくことができるかと思いますし、このアンケートを十分に活かしながら検討してまいりたいと考えているところです。","voiceIndex":68,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"いまだに努力義務だと思っている会社もあるかもしれないし、小さくなればなるほど、そういうことが行われる可能性もあるし、大きければ、そこまで見えてこない部分もあると思いますので、そういうのをしっかりと、各企業とも連携をとって進めていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、何が暴力に当たるのか、身体的なものはもちろん、言葉、経済的、性的、さまざまあるかと思うのですけれども、そういうことの周知も、講演会などさまざまなところで触れていらっしゃるとは思うのですけれども、幅広く伝えていって、私も含めて自分自身をそのとき点検できるような形になっていくと、一歩ずつまた進んでいくのかと思うのですけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"私どもは、その手だてを整えるといいましょうか。何か心配だけれど、とりあえず電話してみて、安心していただく。あるいは重要なケースにつながりましたら、きちんと対応していただけるように努めるものが責務だと考えておるところです。","voiceIndex":72,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"暴力というのは感度の問題や程度の問題ではなく、個人の尊厳を力で奪うもの、踏みにじるものであって、相手がどう思うかというところだと思うのです。それほど批判しているつもりはないのですけれども、そういう意味で、ここで言っている児童、高齢者、障害者、配偶者への暴力やパートナーによる暴力とは何かを改めて伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"受けとめ方がいろいろありますので、相手のことを思いやる心というのが実は人権の一番の大もとだと思っているところですので、まずは相手を思いやる気持ち、そして「あなたのそばにいて大丈夫なんだよ」ということがわかるようなことというのが、本当にふだんの日常生活の中で。","voiceIndex":74,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、暴力のない社会の実現に私も力を尽くしたいと思います。続いて、性的マイノリティについて若干伺いたいのですけれども、資料にある３ページの一番下に、東京都が条例を成立させまして、性自認および性的指向を理由とする不当な差別をしてはならないとしているとありますけれども、区もこの立場と同じなのか。","respondent":"島袋人権啓発課長","answer":"条例に関しての区の考え方ですけれども、区におきましては、やはり人権尊重都市品川宣言がありますので、その宣言文と、やはりまだまだ知っていただけていない部分があるので、そちらを周知するのと同時に、やはり東京２０２０大会は、品川区も開催地域ですので。","voiceIndex":76,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりは、実は理解促進なのか差別禁止なのかという議論がありまして、私は、差別を禁止するために理解を広げていきたいと思っているのですけれども、この議論があるだけに、品川区としては、この性自認および性的指向を理由とする不当な差別をしてはいけないと思っているのかどうか、確認させていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"実は、品川区の人権尊重都市のチラシの後ろ、２３区唯一の人権宣言が２５周年を迎えましたという書き出しで書いているものの中に、やはり性的指向を理由とする偏見や差別をなくそうということで、同性愛者など性的指向に関する少数派の人々への根強い偏見があり。","voiceIndex":78,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もそのとおりだと思います。例えば、最近はどうなのでしょう、あまり聞かないですが、女性だからお酌しなければいけないとか、女性だから優しく接しなければいけないとか、逆に男性だから泣いてはいけない。そうした実態アンケートを実施したり、またこの間、求めてまいりましたが、同性パートナーシップ制度についても前向きに議論を進めていただけたらと思うのですけれども、あわせていかがでしょうか。","respondent":"島袋人権啓発課長","answer":"働き方ももちろん、多様な働き方も含めてなのですけれども、多様な人々が対等な立場でお互いを尊重し、支え合って、ともに生きていく社会というものが、ある意味、共生社会という言葉になるかと思っているのですけれども、この実現のために。","voiceIndex":80,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、ぜひ、どこにやはり違和感や苦しみがあるのか把握するためにも、世田谷区などは実施しているのですけれど、アンケート調査の実施や同性パートナーシップ制度についても前向きな検討が進められたらと思うのですけれども、改めていかがでしょうか。","respondent":"島袋人権啓発課長","answer":"それが悩みだということがありますので、まずはそういったアンケートに自信を持って回答できるような雰囲気というのですか、そういった状況をつくるものも大事ですし、また人権の意識調査などでも、やはり性的マイノリティの方のこと等の設問を検討しておりますので。","voiceIndex":82,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"このパンフレットにありますけれど、しながわ見守りホットライン、２４時間つながりますと、こういうものを、町会の掲示板なり品川区のふれあい掲示板なりに、片隅でもいいですから、常時、皆さんの目に届くようにしていただいて、そういう電話をしたら相談窓口に対しての橋渡しということを今後もやっていただき、多くの人たちの声を聞いて、また励ましてやり、また相談に乗って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に資料の、これが結局、様々な所管課が絡んでくるから、本日は人権啓発課からのということだと思うのですが、虐待防止ネットワーク協議会の役割と構成員で、これは、どういうときにどういうふうに、誰の呼びかけでどういうふうに開かれているのかとか、その辺の情報があれば伺いたいと思います。全庁的な仕組みだと思いますので、今お答えできる範囲で結構ですので、お答えいただきたいのですけれど。","respondent":"島袋人権啓発課長","answer":"なぜ７月に開催になってしまいますかというところなのですけれども、まず年度が変わりまして、７月に実施するに当たりまして、警察に、会議への出席をお願いするに当たりまして、非常に時間がかかるものなので、時間的には４月から動かないと間に合わないということで。","voiceIndex":87,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"本当に命にかかわるというところなのですけれども、基本、１１０番、警察署などだと、何かあったら、もう遠慮なく、どんなケースでも警察署や１１０番に通報していただければと言っていただけるのですけれど、命にかかわるかどうかという判断を誰がするのかということなのです。その辺が、どういうふうに考えられているのかということを伺いたいのと、それからＤＶの所管課は、人権啓発課ですか。","respondent":"島袋人権啓発課長","answer":"は夜間・祝日受付マニュアルというものがございまして、それに基づきまして専用ダイヤル対応をしていますが、本当に、先ほど委員のお話しされた、生命・身体に危険が及ぶと、通報を聞いて感じたときには、通報者本人に１１０番通報をお願いしています。","voiceIndex":89,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"人権啓発課としては人権啓発に関する施策を進めていらっしゃるわけですが、それぞれの所管の施策としては、まずは当事者同士の解決となってしまうと、うっかりすると、このしながわ見守りホットラインが、一番その内容を知られたくない施設に通報が行ってしまったみたいな、あなたたちで解決してくださいみたいになってしまう可能性があるので、その辺を、それぞれの所管でやるべきことは当然として。","respondent":"島袋人権啓発課長","answer":"所管課と人権啓発課のつながりというところですけれども、正直申しまして、やはり生活圏ごとの連携、情報共有が中心で、その後、こちらに上がってくるというシステムにはなってございませんので、まずは各ケース対応というところでしっかりと対応していただき。","voiceIndex":91,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"なかなかやはり人権という視点で全体をつなぐということは、まだまだ始まったばかりなのかと思いますので、それはぜひ人権啓発課がリーダーシップをとるような形で進めていっていただきたいと思います。さっきのデートＤＶなのですけれど、同じことがやはり夫婦間でもあり、経済的ＤＶのことが抜けているので、家庭内のＤＶにも、ぜひ意識を持っていっていただきたいと思います。これは要望です。","respondent":"島袋人権啓発課長","answer":"今まで「マイセルフ」の冊子なのですが、医師会だけに配布していたという経緯がございまして、第５８号からは、医師会、歯科医師会、薬剤師会にも配布するようにお願いしたところ、とても好意的に受けとめてくださいまして。","voiceIndex":93,"id":"exchange-035"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"試行中ということがどういう形で試行されていて、今、検討段階がどの辺まで進んでいて、もしわかれば今後の方向性ということをどのようにお考えか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"１点目は、社会保険労務士の労働環境チェックということを、これはアのところで平成２６年度からと記載させていただいてあります。実は資料にはないのですが、年度途中で区の内部の検討がありまして、平成２６年度の途中から始めたというものです。","voiceIndex":100,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと、(2)の事業・運営状況調査なのですけれど、財務状況の確認というところに、公認会計士が入ってくると理解していいのでしょうかというのが１つ。それから、財務状況は公認会計士だと思うのですが、利用者へのアンケートの内容などはどこで検討されて、どういうふうに実施されたのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"いわゆるこれは監査のようなものですから、非常に時間がかかるというのがありまして、それは社会保険労務士のほうの負担もあった部分がありますので、では評価の仕方について、例えば面接の時間を少し変えてみるとか。","voiceIndex":102,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。生活者ネットワークとしては、ぜひこの評価の仕方は、全施設を対象にしていただきたいというのと、結果についてぜひ公表していただきたいと希望いたしますが、その辺についてコメントはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですので、例えばサイクル、これも毎年全部というのは到底、厳しいので、例えば何年かに１回、例えば５年という１つのサイクルがありますので、その中でどのタイミングでやるかとか、そういったことも含めて検討しています。","voiceIndex":104,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、少なくとも議会の中で指定管理者というのは決めていくわけですし、それから評価もしていると思います。評価というのは厳しい評価ばかりではなくて、こういう指定管理者はすごくやはりいいよねという評価にもつながるわけですから、ぜひその方向で進めていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"多岐にわたって伺いたいと思いますが、資料に、社会保険労務士による労働環境チェックとありますけれども、どのような共通項目でチェックしているのか伺いたいと思います。例えば給与や年休取得率や休暇や超過勤務の実態や労働時間など、さまざま労働環境といっても把握の仕方があるかと思うのですけれども、どこを共通項目としてチェックされているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"労働環境チェックのところですけれども、今ご指摘があったところ、いわゆる一般的に言われる労働の環境、休暇であったり給与の面であったり福利厚生であったり、法令に照らし合わせながらということで、この部分については、ほぼ全てチェック内容に入るというものです。","voiceIndex":108,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"それだけに、労働環境について、モニタリング評価の中なのか、また議決のときなのか、要するに議決や報告のときに、しっかり議会に資料を示していただきたいと思いますが、いかがかということと、従来、区は指定管理者で働いている者の労働条件については把握しないという立場であったかと思いますが、今回の動きというのは、区自身も、例えば平均給与だったり勤続年数だったり。","respondent":"柏原企画調整課長","answer":"お示しの仕方の部分ですけれど、どういった施設をどういったタイミングで出すかといったことも含めて、今、検討しているですので、中身についてはもう少々お時間をいただきながら、お示しできる形に持っていきたいと思ってあります。","voiceIndex":110,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん１点集中というわけではなくて、ここだけのテーマで聞いているという趣旨なのですけれども、先ほど伺ったのは、区はこれまで指定管理者で働いている方の労働条件は把握しないという立場だったけれども、今後は区も把握して、公表の仕方は今検討されているという話はありましたが、区としてもそれぞれの指定管理者、とりわけ社会福祉法人の労働条件を把握するという立場ということなのか。","respondent":"柏原企画調整課長","answer":"繰り返しの部分はあるのですけれども、公の施設としてきちんと運営、事業がなされているか、人云々ということにフォーカスするのではなく、事業を運営するためにきちんとした状態にあるかどうかというのを確認するという趣旨でやってきているものです。","voiceIndex":112,"id":"exchange-042"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"つまり、任意になっているということですよね。たしかにホームページ上も任意になっているのです。ただ、任意であるけれども、その表現というところはまた今後しっかりとご検討をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":41542,"voices":123}},{"id":"h30-20181212-14","meetingId":"h30-cm12","date":"2018年12月12日","dateIso":"2018-12-12","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"改めまして、新公会計制度に関することのうち、財務諸表等の活用","agenda":"改めまして、新公会計制度に関することのうち、財務諸表等の活用","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"１ページ目に、官庁会計は、図のところに単式簿記・現金主義とありますけれども、品川区の新公会計制度というのは、要は企業会計で用いられている考え方の複式簿記・発生主義会計であるのかどうか、確認をお願いしたいと思います。複式簿記・発生主義とは、新公会計制度においては何を意味するのか、簡単に説明していただけないかと思います。","respondent":"齋藤会計管理者","answer":"なぜかというと、わかりにくいのですけれども、先ほどちょっと話をさせてもらった、１００万円の車を買うと、１０年後に廃車するときまで１００万円の価値があるものという形しかできません。それは現金の出と入りがないからです。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"なぜあえて発生主義や減価償却という考え方を導入するのか、伺いたいと思います。","respondent":"齋藤会計管理者","answer":"何が言いたいかというと、インフラ資産というものは５０年、６０年と使うので、今の住民の方ではなくて、将来世代にも負担してもらおうという考え方。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"次に行きます。７ページの上のところに、新公会計制度導入で施設の統廃合を検討することが可能になると書いているのですけれども、なぜ導入することで統廃合を検討することが可能になるのかということを、改めて簡潔にお伺いしたい。最後に、ＰＰＰ／ＰＦＩでの活用も進んでいくと書いてありますけれども、なぜ進んでいくのか、それぞれ簡潔にお伺いしたいと思います。","respondent":"齋藤会計管理者","answer":"１つ目の統廃合の事例は、今までは非コスト情報しか出ておりませんでしたが、コスト情報が出ると維持管理が、例えば財政上、５つあるうち２つしかできない、３つしかできないということになったときに、選択をするにあたっての基礎的な資料となるということになります。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"先ほど地元の事例なども詳細にご説明いただきながら、なかなか大変な状況だと考え聞いておりました。そういう状況になってしまうわけです。企業会計だったら利益を出すことが目的で動いていますから、それでいいのかもしれませんけれども、住民福祉の増進を使命とする自治体の公会計ではなじまないのではないかと思いますが、いかがでしょうか。","respondent":"齋藤会計管理者","answer":"先ほど図書館の例を申し上げましたけれども、例えば全部年金暮らしでお年寄りだから、住民で運営するから残してほしい、そういった議論もあるかもしれませんし、統廃合、廃止ありきではないのだろうと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それが、納税の対価としてのサービスとして認識されるようになってしまう。これはもう削除されましたけれども、こういった全ての福祉サービスを見える化し、コスト主義で考えるやり方というのは、私は区民サービスの削減や低下につながってくると思うのですけれども、いかがでしょうか。新公会計制度で作成される財務諸表等の活用というのは、私は慎重にすべきだと思うのですけれども、いかがでしょうか。","respondent":"齋藤会計管理者","answer":"公会計制度はあくまでフルコストを見ていただく、あるいは財務状況がどのような状況か見せることでありまして、新公会計制度があると福祉サービスが削減されるということはないものと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"私は現状のままで、新公会計制度の活用を進めるのは問題があると思います。この導入によって、施設の統廃合、受益者負担の適正化つまり負担増、あるいは民間委託の推進は、公共サービスの低下が加速することにつながると思います。現状のままで、新公会計制度の活用をどんどん進めていくということには反対です。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"須貝委員","kind":"確認","question":"例えば土地もそうですけれども、公園もそうですし、区有施設、また区が買い取った土地云々があると思うのですが、この中で、ほかの用途にすぐ使える土地、また売却もできるという土地、これは当面売却できない、３０年はだめとか、そういうものもあるので、その辺ももし数字だけでも書いておいていただければ、民間のものに準じて読み取ってくださいということなのですけれども、実際。","respondent":"齋藤会計管理者","answer":"最初のご質問、行政評価シートのことで、７００近い事業がありますが、大分職員は苦労しておりまして、来年度の決算議会でどれほどお出しできるかを検討中で、行く行くはお出ししたいと考えております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今、簿価が最後は１円という話でしたけれども、たしか民間は１０％を残すような、簿価を減価償却で残していると思ったのですが、もし行政が違うやり方なら、それをまた教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"須貝委員からもありましたけれども、説明を改めてお伺いさせていただいて、細かく教えていただきまして、ありがとうございました。そうなったときに、少し今の基金のあり方というのも、せっかくわかりやすくなったのであれば、もっと細分化して、それぞれにこれだけかかるというのが見えるような形に変えていってもいいのかなと思ったのだけれども、そういう考えというのはあるのでしょうか。","respondent":"齋藤会計管理者、品川財政課長","answer":"それが新公会計制度によって、数字的にも裏打ちをして、かつ委員の皆様をはじめ、区民の皆様に、よりご理解いただけるということだと思ってあります。基金の見せ方なのですけれども、当然こういう貸借対照表の中で、資産という形の部分で出していくことになりますので、そういう見せ方についても今後いろいろと検討していきたいと考えています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"必要な施設は当然、更新をしていかなければならないわけです。総くくりで１,０００億円という形にするのか、それとも例えばこういうもので幾ら、こういうもので幾らというのがかかるから、こういうふうになるのだという見せ方でも、私はいいのかなと思いましたので、考え方としてお示しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"ＩＣＴなどの活用に関することのうち、区民サービスの電子化","agenda":"ＩＣＴなどの活用に関することのうち、区民サービスの電子化","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ご説明ありがとうございました。区でもこうした仕組みというのを検討してはいかがかと思うのですけれども、お考えがあれば伺います。","respondent":"山本情報推進課長","answer":"こちらにつきましては、中野区が導入しているということで、調査等をさせていただきまして、導入等をどういった形でできるのかというところも踏まえつつ、関係所管と連携しながら研究をしていきたいと考えています。","voiceIndex":29,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"説明ありがとうございました。多分、私の選択できる学校はどこですかとか、通学区域はどこですかとか、ある程度質問も想定される。選択行動は平成３１年１０月から始まるわけだから、もう１年を切っているわけで、しっかりとしたシステムといいましょうか、きちんと開発をして、これはやってほしいと思うのですけれども、どうでしょうか。","respondent":"山本情報推進課長","answer":"学事制度変更にかかる問い合わせへの対応というところですけれども、まず、ＡＩチャットボット導入を進めるに当たりまして、一番大事なところが、良質なデータを作成して、それをＡＩに学習させていくというところが一番ポイントになってくると考えています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"いいお話が聞けました。そこまで知らなかった。こっちも、要望という形でお話を入れていたのですけれども、絶対そこに質問が集中するのは想定されているわけだから、何とか頑張って１０月に、もっと言うと９月ぐらい、選択行為が始まる前に間に合わせてほしいという思いがありますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"だから、ＡＩを構築するまでに大変な労力が要るということなのですか。それを今日はお聞きしたかったのです。その聞きたいこともさまざまだから、その情報がなかったらＡＩは正確に回答できないわけですから、導入するには膨大な作業を要することなのかなというのを、本日質問したかったのです。ということは、これは相当の労力、時間がかかるのかなと思ったもので、それについてお聞かせください。","respondent":"山本情報推進課長","answer":"所管の状況によるのですけれども、所管のほうで、よくある質問等を既に電子化しているところもありますので、そういったところで導入を進めるということになりましたら、比較的負担は少なくなるのかなとは考えてありますが。","voiceIndex":36,"id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"今、千単位とかいうお話ですけれども、実際は千単位どころではなくて、万単位なのかもしれないと思うのです。そうすると、日本全国これだけ自治体があって、どこかで誰かがやってくれると、その情報を一部修正すれば、区も使いやすいのかなと。そういうところは実際ないのですか。","respondent":"山本情報推進課長","answer":"先行自治体の事例をそのまま、ほかの自治体も使えるようにというところなのですけれども、そこまで詳しく話は聞いていないのですが、そういった形でパッケージ販売とかを今、検討しているという事業者もあると聞いてあります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"それはそれで議会に提案していただければいいのかなと思います。ただ、相当膨大な日数はかかるのだと思いますので、少しずつ、一歩ずつ、慎重に進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"情報推進課で技術的なアドバイスも含めて会議に参加をして、作成の主体は当然、委託先の業者ということで、課としては、アドバイスというか、アプリに関してはどの程度、区としてそういう情報というか、知識というか、蓄積があって、例えばこの1)番のアプリに対しては、具体的にこういうアドバイス等をしてかかわりましたとか、そういう具体例があれば教えていただきたいと思います。","respondent":"山本情報推進課長","answer":"かかわり方というところになりますけれども、例えば4)のしながわ予防接種ナビというところで、今年１１月から始まっているものになりますけれども、対象としてはお子さんを持った、予防接種を受けるような時期になった方がターゲットになってくるのですけれども。","voiceIndex":44,"id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"今後のＩＣＴ活用というところで、１つお伺いしたいと思うのですが、４の（２）番のデジタル化の推進ということで、今後考えていることで、オンライン上での手続の一元化とされているのですけれども、何かもう具体的にどういったことを行うお考えがあるのか、まずその点をお伺いしたいと思います。","respondent":"山本情報推進課長","answer":"国が指定した子育て分野４業務について、ここで手続の電子申請であったり、内容を確認できたりというところでの運用を始めてあります。こちらもこれから本格的に進めていきたいと考えています。","voiceIndex":47,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"そこで、具体的に、こういうものの一元化というのはどうなのかというところなのですけれども、亡くなった後のご家族の方が手続をする戸籍住民課だったり、国保医療年金課だったり、あるいは介護のことだったり、こうした煩雑な手続が、電子化によって一元化をされるということについて、どのようにお考えでしょうか。","respondent":"山本情報推進課長","answer":"ただ、具体的にどう進めていくかというところは、我々のほうには情報はおりてきていないところですけれども、早急に対応できるように準備等はしていきたいと考えています。","voiceIndex":49,"id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうした動きがあるということなので、区としてもそのお考えはお持ちだということですね。ぜひ進めていただきたい分野でありますし、国の動きを待たず、区としてどのようにされていくかというところを、もう一歩お聞きしたいところなのですけれども、本当にこの手続は煩雑なのです。こんな考え方はいかがでしょうか。","respondent":"山本情報推進課長","answer":"ワンストップサービスというお話かと思いますけれども、現状は各課それぞれ所管のシステムを使って、いろいろな手続を処理するということで、例えば国保と戸籍だと、今は別のシステムを使っておりますので、そこの連携というのはできない状態なので。","voiceIndex":51,"id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ研究をしていただいて、やはり品川区はそういったところまでしてくれるのだというところまで、ぜひつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-021"},{"speaker":"新妻委員","kind":"確認","question":"ご説明ありがとうございました。今、ここに４つ挙げられておりまして、若林委員から、所管課との連携がどうなっているのかという確認がありましたけれども、所管課から上がってきたことに対して情報推進課がアドバイスをするという形ですが、逆に情報推進課から、アプリでこういうことができるのだというアドバイスというのはされているのでしょうか。","respondent":"山本情報推進課長","answer":"情報推進課と各課連携の話かと思いますけれども、現在は各所管から上がってきたものに、情報推進課が後から入っていき、一緒に進めていくという方法で進めているところです。","voiceIndex":55,"id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"その情報を持っているのは、やはり情報推進課だと思うので、各課の情報を１つにまとめて、これは１つにできる、例えばアプリがこういうふうに開発ができる、これは電子化ができる等々のアドバイスを、ぜひ情報推進課からしていただきたいと思いますし、それが区民サービスの向上になると思いますが、今後その辺はいかがでしょうか。","respondent":"山本情報推進課長","answer":"システムの連携といいますか、一元化というところは、こちらで必要な部分について研究を進めていきたいと考えているところです。","voiceIndex":57,"id":"exchange-023"}]},{"id":"topic-03","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"正副提案どおりの調査事項でまとめを行うことでよいと思いますけれども、幾つか意見を述べさせていただきたいと思います。庁舎のあり方のところなのですけれども、1)のところで、建物の寿命を鑑みれば、建て替えに係る必要な事項について検討を始める時期とありますけれども、これでは老朽化で建て替え待ったなしという印象を持ちます。しかし、庁舎の寿命というのは、あと１８年あります。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"ですから、報告を上げるときに、当然総意で委員会としての報告は出すにせよ、それぞれ各会派、個人からの意見というのは尊重されるべきなのでしょうから、特定会派から、これはだめとかというのではなくて、総合的に正副で判断をいただいて、つくっていただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":32407,"voices":69}},{"id":"h30-20181213-18","meetingId":"h30-cm12","date":"2018年12月13日","dateIso":"2018-12-13","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２の特定事件調査","agenda":"の２の特定事件調査","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"このオリンピック・パラリンピック教育実践事例集を見ますと、本当に地域に即したとか、それぞれの学校が非常にバラエティに富んだ内容になっているというところがあって、オリンピック・パラリンピック教育との関連という意味では、テーマがオリンピック・パラリンピックの精神、スポーツ、文化、環境となっていますから、そういう意味では非常に幅広い分野をテーマとして捉えているので。","respondent":"熊谷指導課長","answer":"東京都からは「こういったものがありますよ。」という事例が平成２７年度から示されており、それらが掲載されている東京都のホームページを活用することもあります。","voiceIndex":9,"id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"その平成２７年に東京都が示したものというのは、例えばどのようなものがあったのかをちょっと紹介していただけますでしょうか。","respondent":"熊谷指導課長","answer":"」と説明した、そうした授業で内容を紹介したものが事例の一つとして示されています。","voiceIndex":11,"id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"一般に私がそれまで承知していたのは、よくオリンピアンを呼んできていろいろな講演をしてもらうとか、そういう形がやはりスタンダードなのかななどと思っていたのですけれども、やはりオリンピック・パラリンピック教育というものは非常に幅の広いものだということと、そういう意味では各学校のオリジナリティを活かしていけるという方向性は、非常によい方向なのかなという思いを今日は強めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこういうことを聞いているのかというと、この前、厚生委員会でも出てきて、福祉計画のときにも言ったのだけれども、各学校で例えば障害者、それから高齢者、そういう人たちと小学校が触れ合う場、これも教育の一つで行っていて、地域で支えるというのは福祉計画の中にもそういうのが入っていて、じゃあ、教育という形になると、今日もそうなのだけれども、どうしても各学校対応じゃないですか。","respondent":"熊谷指導課長","answer":"もう一つ、国際交流ということもレガシーとして残していく。そのために、今全校で「世界ともだちプロジェクト」に取り組んでいますけれども、それを継続していくことを考えています。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"お願いだけにします。ところが、どういうわけかあの福祉計画をつくったときは、教育委員会の方はお１人しか出席していなくて、基本的には協議会の中では福祉の部門の人が多いわけじゃないですか。授業でやるのと、実際に肌で触れるのと大分ちがうじゃないですか。今度ウィルチェアーラグビーもやられると言っていたけれども、そういう体験と今日みたいな授業というのは全然違うじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけですけれども、「世界ともだちプロジェクト」で気になったのですが、どこの国とどこの学校が交流するかということについては、どなたがお決めになるのでしょうか。","respondent":"熊谷指導課長","answer":"参加予定国の中からオリンピック・パラリンピックを開催した国プラス、４つの国の中から国割りの表がありまして、その中から選んでおります。選んだのは各学校です。","voiceIndex":17,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、東京都で一つのデザインをつくって、その中から各幼稚園や小学校、中学校、義務教育学校等が学校ごとに選んだという判断でよろしいでしょうか。","respondent":"熊谷指導課長","answer":"加えてスイスも追加しています。こうした東京都から示された、バランスよく五大陸が入ったグループから、それぞれの学校・幼稚園が選んだです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"これは教育委員会なのかオリンピック・パラリンピック準備課なのかわからないのですが、このオリンピック・パラリンピック教育実践事例集の４９ページを見ていたときに、アワード校の下のところに、米印で平成３０年度から東京オリンピック・パラリンピック競技大会組織委員会の競技名に準じて「ブラインドサッカー」を「５人制サッカー」と表記しますと出ていたのですが、教育委員会はこれで表記して。","respondent":"辻オリンピック・パラリンピック準備課長、熊谷指導課長","answer":"私どもではいつもブランドサッカーという通称名でずっと通していたもので、大会組織委員会的に、競技名称としては５人制サッカーというのが正式なものです。けれども、都から表彰されるようなときには「５人制サッカー」という表彰になりますので、このようにブラインドサッカーと５人制サッカーを併記する形で、公的に正式名称はお示しするようにしております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"もう一つ、八潮わかば幼稚園の説明の中で、日本人としての自覚と誇りをもってというところなのですけれども、子どもたちが育つ場の中には、今いろいろな国の子どもたちがいます。なのでその子どもたちに対する配慮というか、その部分についてもちょっとお聞かせいただきたいと思うのですが、いかがですか。","respondent":"熊谷指導課長","answer":"市民科のどの部分でというご質問だと思いますけれども、５つの領域の中で、人間関係形成能力というところがあります。","voiceIndex":25,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"私が気になったのは、その幼稚園の中にいるいろいろな国の子どもたちのことで、日本人としての自覚と誇りをその子たちに何か強く求めたりとかしていたら、ちょっとかわいそうだなと思ったので、そういうことはないという確認をさせてください。","respondent":"熊谷指導課長","answer":"やはり国際社会の中で生きていくためには幼児期から多様な文化について知るということが大事です。その際、日本の伝統、文化に誇りを持ってというところは非常に重要だと考えていますので、そこと国際理解との融合した指導をしていくという内容です。","voiceIndex":27,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は日本の伝統や文化というのは大切にしていきたいと考えていますけれども、やはりそれを大切にしていきたいかどうかというのは、子どもたち自身が考えることだと思うのです。なので、その辺はちょっと気をつけていただきたいなと思います。","respondent":"熊谷指導課長","answer":"それは自国の文化でもあり、他国の文化でもあります。自国の文化をしっかり知って、大事にして、そして我が町や自国を大事に思う気持ちがないと、他国のことも愛することができない、理解ができないと思っています。ですので、両輪だと考えています。","voiceIndex":29,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"私もちょっと質問させていただいて大事だというところがあると思うのですが、ほかの学校でも学び方の違いで、そういった貴重な２０２０年の東京オリンピック・パラリンピック競技大会を迎えられるような取り組みというところで言うと、先ほど石田秀男委員もおっしゃっていましたが、もう一歩踏み込んでみんなで組織としてこれをやっていくというような形はあるのかなと思いました。これは意見です。","respondent":"熊谷指導課長","answer":"それを意識してなくさないようにしていく。長野大会のときもそうなのですけれども、当時始まった一校一国運動が今でも続いている。今、始まったばかりの国際交流が、１０年後もつながっていくようにしていきたいと思っているところです。","voiceIndex":31,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"そのあたりというのは長野の場合、どのような形で行われてきているのか。今後東京というくくり、ないし品川区等では、その今もとにあったような形で継続して、もう既にこの今日いただいた冊子の５３ページにもあるとおり、決定しているものだけでも８つあるのですね。その支援という部分での具体的なところはどうやって支えていくのか教えてください。","respondent":"熊谷指導課長","answer":"実際、品川学園でもスカイプを通じた交流を行っているところなのですけれども、教育委員会におきましてもルネサンス予算という、学校がこんなことをやってみたいと考えている夢をかなえるような予算をつけているところですので、そうしたものを活用しながら。","voiceIndex":33,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"これは要望です。日本のパラの選手とかも接する機会はあると思うのですが、そういう教育の場でもそうした機会をぜひ海外のアスリートでパラアスリートと、という機会とか、サッカーとかでそういう機会はあると思うのですが、国同士とかそういったところの機会もこの世界ともだちプロジェクトを通じて、何らかの形で交流できるように考えてほしいと思うのです。何かあれば教えてください。","respondent":"熊谷指導課長","answer":"同じように、城南小学校の事例が１０ページから１３ページに出ているのですけれども、城南小学校では「品川を知る」ということで、昔と今の品川、品川寺の鐘がスイスとつながっているというようなことも含めて学ぶことで、町への愛着や誇りを持つような取り組みをしました。","voiceIndex":35,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"前半のほうのことは、今、中延小学校のところで確認させていただいて、非常にすばらしいなと、子どもたちの感想は大事だなと思って、なので別にどこの国であれ地域であれ、自分が生まれ育ったところに誇りを持てるように促していくという、そういったことも認めていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このオリンピック・パラリンピックの学習の時間が１学年３５時間ということで、西川校長先生のほうからもありましたし、いろいろなところに出ていますけれども、この３５時間というのはどのように確保していくのかなというところで、ここに小学校、例えば延山小学校だったら市民科と体育科と書いてあったり、学校によっては市民科だけだったり、市民科と社会科という形で書いてあるのですけれども。","respondent":"熊谷指導課長","answer":"例えば図工でもいろいろな国の子どもたちの作品を見てそのよさを話し合うですとか、さまざまな教科できちんと意識しながら行っていくということが重要であると考えています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところを、とりわけこれは日本人というところに当てはめて、そこでそれを「日本人としての自覚と誇り」という形で子どもたちに教えていくというのはどうなのかなという違和感があったので、ちょっとそこら辺のところをお聞きしたいのと、もちろん日本人として、その日本の歴史や文化をしっかりと学ぶということはもちろん大事なことだとは思いますけれども。","respondent":"熊谷指導課長","answer":"先ほど国旗のことが出てきたのですけれども、これは外務省のプロトコールによるものなのですが、やはり外国からのお客様をお迎えするときにきちんとしたプロトコールを知らないと、国際人として恥をかいてしまうので。","voiceIndex":40,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"負の歴史も含めて、そういうところをしっかりと学んでいくところは大事だと思いますけれども、その中で、日本人だからできるのだというような形でちょっとここには書かれているという思いがしましたので、日本人としての自覚と誇りというのが日本人だからというのではなく、やはりお互いに国際社会の中で理解し合うところで歴史や伝統をしっかりと学ぶという形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ伺います。今日の授業の内容も大変すばらしかったのです。１点伺いたいのは、今までの質疑の中で出てきていたら申しわけないのですが、この教育において文化プログラムについての扱いは、どのような形で子どもたちに教えていらっしゃるのか。やはりこのオリンピックの一部であるわけなのですけれども、当委員会での調査事項になっていますが、これについてその対応を伺いたいと思います。","respondent":"熊谷指導課長","answer":"平成２８年１月に「東京都オリンピック・パラリンピック教育」実施方針が出されているのですけれども、その中でも東京２０２０オリンピック・パラリンピック競技大会２年前に当たる本年度は、文化プログラムへの参加が、「文化」というテーマの中の「する。","voiceIndex":43,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、この前のスクエア荏原でのUNITE HEART FESTIVAL、あれはしながわ文化プログラムだったのですが、あそこにもお近くの学校の生徒さんには参加するように促したということでしょうか。","respondent":"立川文化観光課長","answer":"いわゆるUNITE HEART FESTIVALにつきましての周知です。チラシにつきましては区内の小学校全校で配布するように依頼したところです。教育委員会のほうから直接というわけではなく、文化観光課のほうから各学校にお願いしたところです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。オリンピック・パラリンピックという観点でのプログラムには、ぜひ品川の子どもたちも文化プログラムとして参加していただきたいということで、ぜひ連携をとっていただいて、教育委員会からもそういうことを推し進めていただきたいのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"文化プログラムと子どもたちとのかかわり、段階的にも子どもたちが文化プログラムに参加する重要な時期にさしかかっていると思いますので、連携をとりながら、子どもたちにも、それから教員にも紹介をして、参加するように呼びかけてまいりたいと思います。","voiceIndex":47,"id":"exchange-021"}]},{"id":"topic-02","title":"の３のその他","agenda":"の３のその他","exchanges":[{"speaker":"鈴木（真）副委員長","kind":"質問","question":"先ほどのUNITE HEART FESTIVALの件、教育委員会でさっき話が出て、これは別の場でも話したのですけれども、ほかの区の関係の会合のときに、このフェスティバルがあるという報告がほんのちょっと出ました。そういうところがちょっとあったので、せっかくやるのにもったいないですから、これからいろいろなことをもう少し積極的にアピールしていってください。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"だからそれは無料でなくて有料でもいいのではないかというのをとても思ったのです。何だかすごく申しわけない気持ちになってしまって、その考え方をちょっと伺いたいと思います。もう一点、「パラスポで新発見。」はスクエア荏原を全館借りての大きなイベントなのでしょうか。この委員会の場では、前回、まだお答えできませんということだったと思うのです。","respondent":"立川文化観光課長、辻オリンピック・パラリンピック準備課長","answer":"UNITE HEART FESTIVALにおける手づくり体験コーナーの関係ですが、こちらはご参加いただける団体の判断ということで、区は関与していないといった状況です。パラリンピックスペシャルデーで使うところなのですが、スクエア荏原の全館ではなくて、ホールとアリーナとイベントホールということで、公園等は使う予定はございません。","voiceIndex":58,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問","question":"このパラリンピックスペシャルデーのことなのですけれども、公園のところは開放するということだったので、その当日利用されている方たちにも、中でこういうイベントをしていますよというような声かけ、わかるようなポスターが貼ってあったりとか、そういう促しはしてほしいなと思うのですが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回は参加自由のパラスポーツ体験がちょっと目立たない感じなので、引っ張ってといいますか、いろいろな方に中に入っていただきたいので、積極的にやっていきたいと思います。","voiceIndex":61,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"当然私も手形を押しましたけれども、本当に重々それはやはり担当の所管の方がよくわかっていらっしゃると思うのですが、イベント自体、これに懲りてやらないということではなくて、今度やるときには本当にしっかり準備をされて、初めてのことですからいろいろなことがあるのは仕方ないと思うのですけれども、みんなが参加してよかったなと思えるイベントにしていただきたいと思います。","respondent":"立川文化観光課長","answer":"委員ご指摘のご意見はごもっともだと考えています。次回、挑戦する機会がありましたら、今回の敗因等を最大限活かしていきたいと考えております。","voiceIndex":63,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"意見","question":"ぜひまとめは必要だと思いますし、いろいろなやり方があるでしょうけれども、正副委員長で方向性を決めていただいて、当オリンピック・パラリンピック推進特別委員会の１年間の議論のまとめとして提出したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":26033,"voices":71}},{"id":"h30-20181218-10","meetingId":"h30-cm12","date":"2018年12月18日","dateIso":"2018-12-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ありがとうございます。それでは、このように申し出をいたします。 次に、(2)区議会防災訓練","agenda":"ありがとうございます。それでは、このように申し出をいたします。 次に、(2)区議会防災訓練","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料No.５で、全国伝統工芸品振興市議会協議会のことなのですけれども、「加入を考えると回答した２３市区議会」とありますけれども、大体、東京の市区町村でそういった手を挙げたところというのはどこなのか、もしわかれば教えてください。","respondent":"久保田区議会事務局長","answer":"正式にはこちらのほうは聞いておりませんけれども、区によって金沢市と連携をしているような区も幾つかあると聞いておりますので、そういった区は参加しようかみたいなことを考えているようなことは聞いております。","voiceIndex":23,"id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"ぜひ確認をお願いしたいと思いますので、よろしくお願いします。","respondent":"久保田区議会事務局長","answer":"わかりました。その旨確認して、各会派のほうにお知らせをしたいと思います。それ以外にも、もし何か確認したいことがあれば、早めにおっしゃっていただければあわせてご確認させていただきたいと思います。","voiceIndex":25,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私もこれを読ませていただいたのですけれども、資料２の「要望内容（案）のイメージ」というところの、「販路の拡大」というところで、伝統工芸青山スクエアというところについての記載があるのですけれども、これはあくまでイメージということなのか、これに賛同して加入するということは、この場所を移動せよということも含めて賛同するというイメージになるのか。","respondent":"久保田区議会事務局長","answer":"特に先方のほうからこれについての説明はこの紙面以外にはございませんので、こういうものがここにあるということは私どもでも確認をしているところですけれども、例えば運営の実態とか、移転に関すること等については把握をしておりませんので。","voiceIndex":27,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"意見","question":"すみません、本当に調べていなくて発言するのは申しわけないのですけれども、私もちょっと調べてみますけれども、これがどういうところが運営をしていて、どういう関係性があるのか。こういうことを言ってしまって大丈夫なのかというところも含めて調べて、次の議会運営委員会で発言したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5310#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":7152,"voices":35}}]);
